# aarch64 binary, need cross objdump. Let's use readelf which is arch-independent for DWARF
# or use python pyelftools
python3 << 'EOF'
from elftools.elf.elffile import ELFFile
from elftools.dwarf.descriptions import describe_form_class

def find_function_for_addr(dwarfinfo, target_addr):
    """Find the function (DW_TAG_subprogram) containing target_addr"""
    for CU in dwarfinfo.iter_CUs():
        for DIE in CU.iter_DIEs():
            if DIE.tag == 'DW_TAG_subprogram':
                try:
                    lo = DIE.attributes.get('DW_AT_low_pc')
                    hi = DIE.attributes.get('DW_AT_high_pc')
                    if lo and hi:
                        lo_val = lo.value
                        hi_val = hi.value
                        # high_pc can be offset from low_pc
                        if describe_form_class(hi.form, CU) == 'constant':
                            hi_val = lo_val + hi_val
                        if lo_val <= target_addr < hi_val:
                            name = DIE.attributes.get('DW_AT_name')
                            if name:
                                return name.value.decode() if isinstance(name.value, bytes) else name.value
                            # Check linkage name
                            ln = DIE.attributes.get('DW_AT_linkage_name')
                            if ln:
                                return ln.value.decode() if isinstance(ln.value, bytes) else ln.value
                except Exception:
                    continue
    return None

with open('/tmp/monosgen_debug.so', 'rb') as f:
    elf = ELFFile(f)
    if elf.has_dwarf_info():
        dwarf = elf.get_dwarf_info()
        for addr in [0x2f4b20, 0x2f4c84]:
            fn = find_function_for_addr(dwarf, addr)
            print(f"0x{addr:x} -> {fn}")
    else:
        print("No DWARF info")
EOF

